-- Xion 3.0 schema. Run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'Community member',role text not null default 'member' check(role in ('member','organization','moderator','admin')),created_at timestamptz not null default now());
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,description text,website text,owner_id uuid references auth.users(id),verified boolean not null default false,created_at timestamptz default now());
create table public.programs(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id),title text not null,organization text not null default '',description text not null default '',city text not null,category text not null,ages text not null default 'All ages',cost text not null default 'Contact provider',image text not null default '✳',scholarship boolean not null default false,latitude double precision,longitude double precision,website text,status text not null default 'pending' check(status in ('pending','published','rejected')),created_at timestamptz default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),program_id uuid not null references public.programs(id) on delete cascade,user_id uuid not null references auth.users(id),rating integer not null check(rating between 1 and 5),body text not null check(char_length(body) between 15 and 1500),status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz default now(),unique(program_id,user_id));
create table public.posts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),title text not null check(char_length(title) between 8 and 120),body text not null check(char_length(body) between 20 and 3000),topic text not null default 'Questions',status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz default now());
create table public.comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,parent_id uuid references public.comments(id),user_id uuid not null references auth.users(id),body text not null check(char_length(body) between 2 and 2000),status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz default now());
create table public.favorites(user_id uuid references auth.users(id) on delete cascade,program_id uuid references public.programs(id) on delete cascade,created_at timestamptz default now(),primary key(user_id,program_id));
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references auth.users(id),target_type text not null check(target_type in ('review','post','comment','program')),target_id uuid not null,reason text not null,created_at timestamptz default now());
create index programs_search_idx on public.programs(status,city,category);create index posts_feed_idx on public.posts(status,created_at desc);create index reviews_program_idx on public.reviews(program_id,status);
create function public.is_mod() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=(select auth.uid()) and role in ('moderator','admin')) $$;
-- Only an existing admin can change profile roles via trusted server-side management; do not add a user-facing role update policy.
alter table public.profiles enable row level security;alter table public.organizations enable row level security;alter table public.programs enable row level security;alter table public.reviews enable row level security;alter table public.posts enable row level security;alter table public.comments enable row level security;alter table public.favorites enable row level security;alter table public.reports enable row level security;
create policy "profile self read" on public.profiles for select to authenticated using(id=(select auth.uid()) or public.is_mod());
create policy "profile self create" on public.profiles for insert to authenticated with check(id=(select auth.uid()) and role='member');
create policy "org public read" on public.organizations for select using(true);
create policy "org owner create" on public.organizations for insert to authenticated with check(owner_id=(select auth.uid()) and verified=false);
create policy "org owner edit" on public.organizations for update to authenticated using(owner_id=(select auth.uid()) or public.is_mod()) with check(owner_id=(select auth.uid()) or public.is_mod());
create policy "program public read" on public.programs for select using(status='published' or public.is_mod() or exists(select 1 from public.organizations o where o.id=organization_id and o.owner_id=(select auth.uid())));
create policy "program owner submit" on public.programs for insert to authenticated with check(status='pending' and exists(select 1 from public.organizations o where o.id=organization_id and o.owner_id=(select auth.uid())));
create policy "program mod update" on public.programs for update to authenticated using(public.is_mod()) with check(public.is_mod());
create policy "review approved read" on public.reviews for select using(status='approved' or user_id=(select auth.uid()) or public.is_mod());
create policy "review submit" on public.reviews for insert to authenticated with check(user_id=(select auth.uid()) and status='pending');
create policy "review mod" on public.reviews for update to authenticated using(public.is_mod()) with check(public.is_mod());
create policy "post approved read" on public.posts for select using(status='approved' or user_id=(select auth.uid()) or public.is_mod());
create policy "post submit" on public.posts for insert to authenticated with check(user_id=(select auth.uid()) and status='pending');
create policy "post mod" on public.posts for update to authenticated using(public.is_mod()) with check(public.is_mod());
create policy "comment approved read" on public.comments for select using((status='approved' and exists(select 1 from public.posts p where p.id=post_id and p.status='approved')) or user_id=(select auth.uid()) or public.is_mod());
create policy "comment submit" on public.comments for insert to authenticated with check(user_id=(select auth.uid()) and status='pending' and exists(select 1 from public.posts p where p.id=post_id and p.status='approved'));
create policy "comment mod" on public.comments for update to authenticated using(public.is_mod()) with check(public.is_mod());
create policy "favorite own" on public.favorites for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy "report submit" on public.reports for insert to authenticated with check(reporter_id=(select auth.uid()));
create policy "report mod read" on public.reports for select to authenticated using(public.is_mod());
